                    <div class="relative overflow-hidden"><div class="product-image-frame aspect-[1.15]">@if ($product->image)<img src="{{ product_image_url($product->image) }}" alt="{{ $product->name }}" loading="lazy" class="h-full w-full object-cover transition duration-700 group-hover:scale-105">@else<span class="font-script text-4xl text-bordo/60">{{ $product->name }}</span><span class="mt-1 text-[9px] font-bold uppercase tracking-[0.14em] text-bordo/45">próximamente</span>@endif</div><span class="absolute left-4 top-4 rounded-full bg-crema/90 px-3 py-2 text-[10px] font-bold uppercase tracking-[0.1em] text-bordo">Pedilo con {{ $product->lead_time_hours }} h</span>@if($product->is_featured)<span class="absolute right-4 top-4 rounded-full bg-caramelo px-3 py-2 text-[10px] font-bold uppercase tracking-[0.1em] text-white">Destacado</span>@endif</div>
