    <div x-show="selectedProduct" x-cloak x-transition.opacity class="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-ink/55 p-4 sm:p-8" @keydown.escape.window="closeProduct()" @click.self="closeProduct()" role="dialog" aria-modal="true" aria-labelledby="product-modal-title">
        <div x-show="selectedProduct" x-transition:enter="transition ease-out duration-300" x-transition:enter-start="translate-y-5 scale-95 opacity-0" x-transition:enter-end="translate-y-0 scale-100 opacity-100" class="my-5 grid w-full max-w-4xl overflow-hidden rounded-[2rem] bg-crema shadow-2xl md:grid-cols-2" @click.stop>
            <div class="product-modal-image relative min-h-72 md:min-h-full"><template x-if="selectedProduct?.image"><img :src="selectedProduct?.image" :alt="selectedProduct?.name" class="absolute inset-0 h-full w-full object-cover"></template><template x-if="!selectedProduct?.image"><div class="absolute inset-0 grid place-items-center p-8 text-center"><span class="font-script text-6xl text-bordo/65" x-text="selectedProduct?.name"></span></div></template><button type="button" @click="closeProduct()" class="absolute right-4 top-4 grid h-10 w-10 place-items-center rounded-full bg-crema/90 text-2xl leading-none text-bordo" aria-label="Cerrar detalle">&times;</button></div>
            <div class="max-h-[88vh] overflow-y-auto p-6 sm:p-9"><p class="eyebrow" x-text="selectedProduct?.category"></p><h2 id="product-modal-title" class="mt-2 font-display text-3xl text-bordo" x-text="selectedProduct?.name"></h2><p class="mt-4 text-sm leading-7 text-ink/70" x-text="selectedProduct?.description"></p><div class="mt-6"><p class="text-xs font-bold uppercase tracking-[0.12em] text-bordo">Elegí el tamaño</p><div class="mt-3 grid gap-2"><template x-for="size in (selectedProduct?.sizes || [])" :key="size.id"><button type="button" @click="selectedSize = size.id" :disabled="size.quantity === 0" :class="selectedSize === size.id ? 'border-bordo bg-blush' : 'border-bordo/10 bg-white'" class="flex items-center justify-between rounded-2xl border px-4 py-3 text-left transition disabled:cursor-not-allowed disabled:opacity-40"><span><span class="block text-sm" x-text="size.label"></span><span class="mt-1 block text-[11px] text-ink/50" x-text="size.quantity > 0 ? `Disponible: ${size.quantity}` : 'Sin stock'"></span></span><strong class="text-sm text-bordo" x-text="money(size.price)"></strong></button></template></div></div><div x-show="(selectedProduct?.colors || []).length" class="mt-6"><p class="text-xs font-bold uppercase tracking-[0.12em] text-bordo">Elegí un color</p><div class="mt-3 flex flex-wrap gap-2"><template x-for="color in (selectedProduct?.colors || [])" :key="color.id"><button type="button" @click="selectedColor = color.id" :class="selectedColor === color.id ? 'ring-2 ring-bordo ring-offset-2' : ''" class="flex items-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-ink transition" :aria-label="`Elegir ${color.name}`"><span class="h-5 w-5 rounded-full border border-ink/15" :style="`background-color: ${color.hex}`"></span><span x-text="color.name"></span></button></template></div></div><div class="mt-6 grid gap-5 sm:grid-cols-2"><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-bordo">Ingredientes</p><ul class="mt-2 space-y-1.5 text-xs leading-5 text-ink/65"><template x-for="ingredient in (selectedProduct?.ingredients || [])" :key="ingredient.name"><li><span class="font-semibold text-ink" x-text="ingredient.name"></span> · <span x-text="ingredient.origin"></span></li></template></ul></div><div><p class="text-xs font-bold uppercase tracking-[0.12em] text-bordo">Alérgenos</p><div class="mt-2 flex flex-wrap gap-1.5"><template x-for="allergen in (selectedProduct?.allergens || [])" :key="allergen"><span class="rounded-full bg-white px-2.5 py-1 text-[10px] font-semibold text-ink/65" x-text="allergen"></span></template></div></div></div><div class="mt-5 rounded-2xl bg-white p-3 text-xs leading-5 text-ink/65"><strong class="text-bordo">Conservación:</strong> <span x-text="selectedProduct?.storage_instructions"></span><br><strong class="text-bordo">Anticipación:</strong> Pedilo con <span x-text="selectedProduct?.lead_time_hours"></span> horas.</div><div class="mt-6 flex items-center gap-3"><label class="text-xs font-bold uppercase tracking-[0.12em] text-bordo" for="product-quantity">Cantidad</label><div class="flex items-center rounded-full bg-white"><button type="button" @click="detailQuantity = Math.max(1, detailQuantity - 1)" class="grid h-10 w-10 place-items-center text-bordo" aria-label="Restar cantidad">−</button><span class="w-6 text-center text-sm font-bold" x-text="detailQuantity"></span><button type="button" @click="detailQuantity = Math.min(sizeFor({ product_id: selectedProduct.id, size_id: selectedSize })?.quantity || 1, detailQuantity + 1)" class="grid h-10 w-10 place-items-center text-bordo" aria-label="Sumar cantidad">+</button></div></div><label class="mt-5 block"><span class="text-xs font-bold uppercase tracking-[0.12em] text-bordo">Nota opcional</span><textarea x-model="detailNote" rows="2" class="mt-2 w-full resize-none rounded-2xl border-0 bg-white p-3 text-sm text-ink placeholder:text-ink/35 focus:ring-2 focus:ring-rosa-viejo" placeholder="Ej: sin decoración de chocolate"></textarea></label><button type="button" @click="addSelectedToCart()" :disabled="!sizeFor({ product_id: selectedProduct?.id, size_id: selectedSize })?.quantity" class="btn-primary mt-5 w-full disabled:cursor-not-allowed disabled:opacity-45">Agregar al carrito <span x-text="selectedSize ? money(sizeFor({ product_id: selectedProduct.id, size_id: selectedSize })?.price || 0) : ''"></span></button></div>
        </div>
    </div>
</section>
